function newCharacter(){const stats=Object.fromEntries(STATS.map(x=>[x,x==='BODY'?8:6]));const skills=Object.fromEntries(SKILLS.map(s=>[s[0],s[4]?2:0]));return {id:safeId(),name:'',role:'solo',rank:4,stats,skills,hp:45,humanity:60,head:0,bodyArmor:0,native:'',gear:'',cyberware:'',notes:''}}
