function appShell(content){return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">N<span>C</span><i>✳</i></div><div><strong>NIGHT CITY</strong><small>// RED COMPANION</small></div></div><div class="sidebar-label">${tr('private')}</div><nav class="nav">${['overview','characters','rules','dice'].map(v=>`<button class="nav-item ${state.view===v||(state.view==='sheet'&&v==='characters')?'active':''}" data-action="navigate" data-view="${v}"><span class="nav-icon">${icons[v]}</span>${tr(v)}<span class="nav-arrow">↗</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="status"><span class="status-dot"></span> SYSTEM ONLINE</div><p>${tr('browser')}</p><div class="version">EDITION 2045 <span>V 1.0</span></div></div></aside><main class="main"><header class="topbar"><div class="top-context"><span class="cross">✳</span><span>${tr('appLabel')}</span><span class="slash">/</span><strong>${tr(state.view==='sheet'?'sheet':state.view)}</strong></div><div class="top-actions"><span class="top-id">NC // 2045</span><div class="lang-switch"><button data-action="lang" data-lang="ru" class="${state.lang==='ru'?'selected':''}">RU</button><button data-action="lang" data-lang="en" class="${state.lang==='en'?'selected':''}">EN</button></div><button class="avatar" data-action="navigate" data-view="characters" aria-label="${tr('characters')}">✳</button></div></header><div class="content">${content}<footer class="footer"><span>${tr('notOfficial')}</span><span>MADE FOR THE TIME OF THE RED // 2045</span></footer></div></main></div>`}
function createBtn(){return `<button class="btn primary" data-action="new"><span>＋</span> ${tr('new')}</button>`}
function charCard(c){const role=window.ROLES.find(r=>r.id===c.role);return `<article class="character-card"><div class="char-art"><div class="char-art-grid"></div><span class="char-art-glyph">${esc((c.name||'N').slice(0,1).toUpperCase())}</span><span class="char-index">NC // ${esc(c.role.toUpperCase())}</span><span class="char-dot">✳</span></div><div class="char-body"><div class="char-kicker">${esc(val(role?.name)||c.role)} <span> / RANK ${Number(c.rank)||0}</span></div><h3>${esc(c.name||tr('untitled'))}</h3><div class="char-meta"><span>HP <strong>${Number(c.hp)||0}/${hpMax(c)}</strong></span><span>HUM <strong>${Number(c.humanity)||0}</strong></span><span>BODY <strong>${Number(c.stats.BODY)||0}</strong></span></div><button class="btn text-button" data-action="open" data-id="${esc(c.id)}">${tr('edit')} <span>↗</span></button></div></article>`}
function empty(){return `<div class="empty"><div class="empty-icon">✳</div><h3>${tr('empty')}</h3><p>${tr('emptyDesc')}</p>${createBtn()}</div>`}
function overview(){return `<div class="eyebrow"><span class="red-dot"></span> ${tr('subtitle')} <span> // 001</span></div><section class="hero"><div class="hero-copy"><div class="hero-label"><span>✳</span> ${tr('tag')}</div><h1>${tr('hero').replace('\n','<br>')}</h1><p>${tr('intro')}</p><div class="hero-actions">${createBtn()}<button class="btn ghost" data-action="navigate" data-view="rules">${tr('openRules')} <span>↗</span></button></div></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="hero-sun"></div><div class="hero-cross">✳</div><div class="hero-coordinate">N 35° 41' 23"<br>W 120° 45' 10"</div><div class="hero-big">NC<span>///</span></div><div class="hero-side">NIGHT CITY &nbsp; • &nbsp; EST. 1994 &nbsp; • &nbsp; 2045</div></div><div class="hero-bottom"><span>WELCOME TO THE TIME OF THE RED</span><span>01 / 04</span></div></section><div class="section-head"><div><div class="overline">01 / PERSONNEL</div><h2>${tr('library')}</h2><p>${tr('libraryIntro')}</p></div><button class="btn subtle" data-action="navigate" data-view="characters">${tr('characters')} <span>↗</span></button></div><div class="character-grid">${state.characters.length?state.characters.slice(0,3).map(charCard).join(''):empty()}</div><div class="section-head"><div><div class="overline">02 / DATABASE</div><h2>${tr('quick')}</h2></div></div><div class="quick-grid"><button class="quick-card" data-action="navigate" data-view="rules"><span class="quick-icon">▥</span><span><b>${tr('quickRules')}</b><small>${tr('quickRulesSub')}</small></span><span class="quick-arrow">↗</span></button><button class="quick-card" data-action="navigate" data-view="dice"><span class="quick-icon">⬡</span><span><b>${tr('quickDice')}</b><small>${tr('quickDiceSub')}</small></span><span class="quick-arrow">↗</span></button></div><div class="source-strip"><div class="source-symbol">✳</div><div><strong>${tr('source')}</strong><p>${tr('sourceDesc')}</p></div></div>`}
function characters(){return `<div class="page-header"><div><div class="overline">01 / PERSONNEL DATABASE</div><h1>${tr('charactersTitle')}</h1><p>${tr('charsLead')}</p></div><div class="header-actions"><label class="btn ghost file-label">↓ ${tr('import')}<input type="file" accept="application/json,.json" id="import-file" hidden></label>${createBtn()}</div></div><div class="countbar"><span>${tr('library')}</span><b>${String(state.characters.length).padStart(2,'0')} / 2045</b></div><div class="character-grid">${state.characters.length?state.characters.map(charCard).join(''):empty()}</div>`}
function rules(){let q=state.query.toLowerCase().trim();let list=window.RULES.filter(r=>!q||[val(r.title),val(r.text),val(r.category),String(r.page)].some(x=>x.toLowerCase().includes(q)));return `<div class="page-header"><div><div class="overline">02 / KNOWLEDGE DATABASE</div><h1>${tr('rulesTitle')}</h1><p>${tr('rulesLead')}</p></div><div class="header-marker">✳<small>COREBOOK<br>V1.22</small></div></div><div class="rules-toolbar"><label class="search"><span>⌕</span><input id="rules-search" value="${esc(state.query)}" placeholder="${tr('search')}" aria-label="${tr('search')}"><kbd>⌕</kbd></label><span class="result-count">${String(list.length).padStart(2,'0')} ${tr('showing')}</span></div><div id="rules-list" class="rules-grid">${rulesCards(list)}</div>`}
function rulesCards(list){return list.length?list.map((r,i)=>`<article class="rule-card"><div class="rule-top"><span class="badge">${esc(val(r.category))}</span><span>${tr('page')} ${esc(r.page)}</span></div><h3>${esc(val(r.title))}</h3><p>${esc(val(r.text))}</p><div class="rule-bottom"><span>COREBOOK // ${String(i+1).padStart(2,'0')}</span><span>↗</span></div></article>`).join(''):`<div class="empty compact"><div class="empty-icon">⌕</div><p>${tr('noResults')}</p></div>`}
function dice(){return `<div class="page-header"><div><div class="overline">03 / PROBABILITY ENGINE</div><h1>${tr('diceTitle')}</h1><p>${tr('diceLead')}</p></div><div class="header-marker">⬡<small>RANDOM<br>GENERATOR</small></div></div><div class="dice-grid"><section class="card dice-card"><div class="card-heading"><span>${tr('check')}</span><span>01 / D10</span></div><div class="dice-visual">⬡<span>D10</span></div><h2>${tr('diceFormula')}</h2><p class="muted">${tr('critNote')}</p><div class="form-grid three"><label class="field">${tr('statValue')}<input type="number" id="roll-stat" value="6" min="0" max="20"></label><label class="field">${tr('skillValue')}<input type="number" id="roll-skill" value="4" min="0" max="20"></label><label class="field">${tr('modifier')}<input type="number" id="roll-mod" value="0" min="-100" max="100"></label></div><button class="btn primary wide" data-action="roll-check">${tr('roll')} ↗</button></section><div><section class="card"><div class="card-heading"><span>${tr('freeRoll')}</span><span>02 / DICE</span></div><div class="form-grid two"><label class="field">${tr('number')}<input type="number" id="roll-count" min="1" max="50" value="1"></label><label class="field">${tr('sides')}<select id="roll-sides"><option>6</option><option>10</option><option>4</option><option>8</option><option>12</option><option>20</option><option>100</option></select></label></div><button class="btn ghost wide" data-action="roll-free">${tr('roll')} ↗</button></section><section class="card history-card"><div class="card-heading"><span>${tr('history')}</span><button class="text-link" data-action="clear-history">${tr('clear')}</button></div><div id="history-list">${historyRows()}</div></section></div></div>`}
function historyRows(){return state.history.length?state.history.map(r=>`<div class="history-row"><div><strong>${esc(r.label)}</strong><small>${esc(r.detail)}</small></div><b>${esc(r.total)}</b></div>`).join(''):`<p class="muted">${tr('noRolls')}</p>`}
function input(label,key,value,type='text',extra=''){return `<label class="field">${label}<input type="${type}" data-field="${key}" value="${esc(value)}" ${extra}></label>`}
function sheet(c){if(!c){state.view='characters';return characters()}const sum=statSum(c),used=points(c),max=hpMax(c),role=window.ROLES.find(r=>r.id===c.role),badReq=SKILLS.some(s=>s[4]&&Number(c.skills[s[0]])<2);return `<div class="sheet-top"><button class="back-link" data-action="navigate" data-view="characters">← ${tr('back')} / ${tr('characters')}</button><span class="saved-indicator"><span class="status-dot"></span> ${tr('saved')}</span></div><div class="page-header sheet-header"><div><div class="overline">PERSONNEL FILE / ${esc(c.role.toUpperCase())}</div><h1 data-calc="character-name">${esc(c.name||tr('untitled'))}</h1><p data-calc="role-description">${esc(val(role?.description)||'')}</p></div><div class="header-actions"><button class="btn ghost" data-action="export">↓ ${tr('export')}</button><button class="btn ghost" data-action="print">↗ ${tr('print')}</button></div></div><div class="sheet-layout"><div class="sheet-primary"><section class="card"><div class="card-heading"><span>${tr('identity')}</span><span>01 / ID</span></div><div class="form-grid three">${input(tr('handle'),'name',c.name,'text',`placeholder="${tr('namePlaceholder')}" maxlength="80"`)}<label class="field">${tr('role')}<select data-field="role">${window.ROLES.map(r=>`<option value="${esc(r.id)}" ${c.role===r.id?'selected':''}>${esc(val(r.name))}</option>`).join('')}</select></label>${input(tr('roleRank'),'rank',c.rank,'number','min="1" max="10"')}</div></section><section class="card"><div class="card-heading"><span>${tr('stats')}</span><span data-calc="stats">${sum} / 62</span></div><p class="muted">${tr('statsHelp')}</p><div class="stats-grid">${STATS.map(s=>`<label class="stat"><span>${s}</span><input type="number" min="2" max="8" data-stat="${s}" value="${Number(c.stats[s])}"></label>`).join('')}</div><div data-calc="stat-budget" class="budget-line ${sum===62?'good':'warn'}"><span>${sum===62?'● '+tr('statBudgetOk'):'● '+tr('spendWarn')}</span><b>${tr('remaining')}: ${62-sum}</b></div></section><section class="card"><div class="card-heading"><span>${tr('skills')}</span><span data-calc="skills">${used} / 86</span></div><p class="muted">${tr('skillsHelp')}</p><div class="skills-list">${SKILLS.map(s=>`<div class="skill-row"><div><strong>${esc(state.lang==='ru'?s[1]:s[0])}</strong><small>${s[2]} ${s[3]===2?' · ×2':''}${s[4]?' · '+tr('required'):''}</small></div><input aria-label="${esc(s[0])}" type="number" data-skill="${esc(s[0])}" value="${Number(c.skills[s[0]])||0}" min="0" max="10"><button class="skill-roll" data-action="skill-roll" data-skill="${esc(s[0])}" title="${tr('quickRoll')}">⬡</button></div>`).join('')}</div><div data-calc="skill-budget" class="budget-line ${used===86&&!badReq&&!SKILLS.some(s=>Number(c.skills[s[0]])>6)?'good':'warn'}"><span>${badReq?tr('needSkill'):used===86&&!SKILLS.some(s=>Number(c.skills[s[0]])>6)?tr('skillBudgetOk'):tr('spendWarn')}</span><b>${tr('skillPoints')}: ${used}/86</b></div>${input(tr('native'),'native',c.native,'text',`placeholder="${tr('nativeHelp')}"`) }<p class="help">${tr('nativeHelp')}</p></section><section class="card"><div class="card-heading"><span>${tr('inventory')}</span><span>04 / LOADOUT</span></div>${['gear','cyberware','notes'].map(k=>`<label class="field textarea-field">${tr(k)}<textarea data-field="${k}" placeholder="${tr('write')}" rows="4">${esc(c[k])}</textarea></label>`).join('')}</section><button class="delete-button" data-action="delete">✕ ${tr('delete')}</button></div><aside class="sheet-aside"><section class="card condition"><div class="card-heading"><span>${tr('vitals')}</span><span>02 / LIVE</span></div><div class="hp-display"><span>${tr('hp')}</span><div><input type="number" data-field="hp" min="0" value="${Number(c.hp)||0}" aria-label="${tr('hp')}"><i data-calc="max-hp">/ ${max}</i></div><small>MAX HP</small></div><div class="condition-rows"><div><span>${tr('serious')}</span><strong data-calc="serious">&lt; ${Math.ceil(max/2)}</strong></div><div><span>${tr('death')}</span><strong data-calc="death">${Number(c.stats.BODY)}</strong></div><div><span>${tr('maxHumanity')}</span><strong data-calc="max-humanity">${Number(c.stats.EMP)*10}</strong></div><div><span>${tr('currentEmp')}</span><strong data-calc="current-emp">${Math.max(0,Math.floor(Number(c.humanity)/10))}</strong></div></div>${input(tr('humanity'),'humanity',c.humanity,'number','min="0" max="100"')}<div class="form-grid two">${input(tr('head')+' SP','head',c.head,'number','min="0"')}${input(tr('bodyArmor')+' SP','bodyArmor',c.bodyArmor,'number','min="0"')}</div></section><section class="note-card"><span>✳ ${tr('guide')}</span><p>${tr('sheetHint')}</p></section></aside></div>`}
function render(){let content=state.view==='overview'?overview():state.view==='characters'?characters():state.view==='rules'?rules():state.view==='dice'?dice():sheet(active());$('#app').innerHTML=appShell(content);document.documentElement.lang=state.lang;document.title='Night City // RED — '+tr('appLabel')}
function pushRoll(label,detail,total){state.history.unshift({label,detail,total});state.history=state.history.slice(0,20);save()}
function checkRoll(stat,skill,mod,label){const first=d(10),extra=first===1||first===10?d(10):0,total=first+(first===1?-extra:extra)+stat+skill+mod;let crit=first===10?tr('criticalSuccess'):first===1?tr('criticalFailure'):'';pushRoll(label||tr('rollCheck'),`1d10 ${first}${extra?` ${first===1?'−':'+'} ${extra} (${crit})`:''} + ${stat} + ${skill} ${mod?`${mod>0?'+':'−'} ${Math.abs(mod)}`:''}`,total);return {total,crit,first,extra}}
function validateCharacter(c){return c&&typeof c==='object'&&typeof c.name==='string'&&c.stats&&typeof c.stats==='object'&&c.skills&&typeof c.skills==='object'&&STATS.every(s=>Number.isFinite(Number(c.stats[s]))&&Number(c.stats[s])>=0&&Number(c.stats[s])<=20)&&SKILLS.every(s=>c.skills[s[0]]==null||(Number.isFinite(Number(c.skills[s[0]]))&&Number(c.skills[s[0]])>=0&&Number(c.skills[s[0]])<=10))}
$('#app').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='navigate'){state.view=b.dataset.view;state.active=null;state.query='';render();window.scrollTo(0,0)}else if(a==='lang'){state.lang=b.dataset.lang;save();render()}else if(a==='new'){let c=newCharacter();state.characters.unshift(c);state.active=c.id;state.view='sheet';save();render();window.scrollTo(0,0)}else if(a==='open'){state.active=b.dataset.id;state.view='sheet';render();window.scrollTo(0,0)}else if(a==='delete'){if(confirm(tr('deleteConfirm'))){state.characters=state.characters.filter(c=>c.id!==state.active);state.active=null;state.view='characters';save();render()}}else if(a==='export'){let c=active();let blob=new Blob([JSON.stringify({format:'nightcity-red-character',version:1,character:c},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='night-city-character.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a==='print'){window.print()}else if(a==='clear-history'){state.history=[];save();render()}else if(a==='roll-check'){let num=id=>Number($(id).value)||0;checkRoll(num('#roll-stat'),num('#roll-skill'),num('#roll-mod'));render()}else if(a==='roll-free'){let n=Math.max(1,Math.min(50,Number($('#roll-count').value)||1)),s=Math.max(2,Math.min(100,Number($('#roll-sides').value)||6)),rolls=Array.from({length:n},()=>d(s));pushRoll(`${n}d${s}`,rolls.join(' + '),rolls.reduce((x,y)=>x+y,0));render()}else if(a==='skill-roll'){let c=active(),s=SKILLS.find(s=>s[0]===b.dataset.skill);if(!c||!s)return;let out=checkRoll(s[2]==='EMP'?Math.max(0,Math.floor(Number(c.humanity)/10)):(Number(c.stats[s[2]])||0),Number(c.skills[s[0]])||0,0,state.lang==='ru'?s[1]:s[0]);alert(`${state.lang==='ru'?s[1]:s[0]}: ${out.total}\n${state.history[0].detail}`)}});
$('#app').addEventListener('change',async e=>{let el=e.target,c=active();if(el.id==='import-file'){const file=el.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());const obj=data.character||data;if(!validateCharacter(obj))throw Error('invalid');const clean={...newCharacter(),...obj,id:safeId(),stats:{...newCharacter().stats,...obj.stats},skills:{...newCharacter().skills,...obj.skills}};state.characters.unshift(clean);state.active=clean.id;state.view='sheet';save();render()}catch{alert(tr('importError'));el.value=''}return}if(!c)return;updateField(el,c);refreshSheet(c)});
function updateField(el,c){if(el.dataset.field){let k=el.dataset.field;c[k]=el.type==='number'?Math.max(Number(el.min)||0,Math.min(Number(el.max)||1000,Number(el.value)||0)):el.value.slice(0,10000)}if(el.dataset.stat)c.stats[el.dataset.stat]=Math.max(2,Math.min(8,Number(el.value)||2));if(el.dataset.skill)c.skills[el.dataset.skill]=Math.max(0,Math.min(10,Number(el.value)||0));save()}
function refreshSheet(c){let set=(id,text)=>{const x=$(`[data-calc="${id}"]`);if(x)x.textContent=text};let sum=statSum(c),used=points(c),max=hpMax(c),bad=SKILLS.some(s=>s[4]&&Number(c.skills[s[0]])<2),above=SKILLS.some(s=>Number(c.skills[s[0]])>6);set('character-name',c.name||tr('untitled'));set('role-description',val(window.ROLES.find(r=>r.id===c.role)?.description));set('stats',sum+' / 62');set('skills',used+' / 86');set('max-hp','/ '+max);set('serious','< '+Math.ceil(max/2));set('death',String(c.stats.BODY));set('max-humanity',String(Number(c.stats.EMP)*10));set('current-emp',String(Math.max(0,Math.floor(Number(c.humanity)/10))));let sb=$('[data-calc="stat-budget"]'),kb=$('[data-calc="skill-budget"]');if(sb){sb.className='budget-line '+(sum===62?'good':'warn');sb.children[0].textContent='● '+tr(sum===62?'statBudgetOk':'spendWarn');sb.children[1].textContent=tr('remaining')+': '+(62-sum)}if(kb){kb.className='budget-line '+(used===86&&!bad&&!above?'good':'warn');kb.children[0].textContent=bad?tr('needSkill'):used===86&&!above?tr('skillBudgetOk'):tr('spendWarn');kb.children[1].textContent=tr('skillPoints')+': '+used+'/86'}}
$('#app').addEventListener('input',e=>{let el=e.target;if(el.id==='rules-search'){state.query=el.value;let q=state.query.toLowerCase().trim(),list=window.RULES.filter(r=>!q||[val(r.title),val(r.text),val(r.category),String(r.page)].some(x=>x.toLowerCase().includes(q)));$('#rules-list').innerHTML=rulesCards(list);let count=$('.result-count');if(count)count.textContent=String(list.length).padStart(2,'0')+' '+tr('showing');return}let c=active();if(c&&(el.dataset.field||el.dataset.stat||el.dataset.skill)){updateField(el,c);refreshSheet(c)}});
render();

